?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RT ESCAPE · Régie</title><link rel="stylesheet" href="/assets/app.css"></head><body class="admin live-cockpit"><header class="admin-top"><div class="header-brand"><img class="rt-escape-logo compact-logo" src="/assets/rt-escape-logo.png" alt="RT ESCAPE"><span class="brand-context">RÉGIE LIVE</span></div><div class="cockpit-status"><i></i> LIVE · <?=e($g['code'])?></div><a class="btn" target="_blank" href="/game/screen.php?code=<?=e(rawurlencode($g['code']))?>">📺 ÉCRAN SALLE</a><a href="/admin/index.php">← Sortir</a></header>
