<section class="cockpit-card transmit-card"><div class="card-head"><div><span class="eyebrow">BOÎTE AUX LETTRES</span><h2>Transmission instantanée</h2></div><span class="fast-badge">1 CLIC</span></div><div class="target-row"><label>DESTINATAIRE</label><select id="target"><option value="0">👥 TOUS LES JOUEURS</option><?php foreach($players as $p): ?><option value="<?=$p['id']?>">👤 <?=e($p['name'])?></option><?php endforeach; ?></select></div><div class="quick-types"><button class="active" data-type="text" onclick="pickType(this,'text')">💬 MESSAGE</button><button data-type="image" onclick="pickType(this,'image')">🖼 IMAGE</button><button data-type="video" onclick="pickType(this,'video')">🎬 VIDÉO</button><button data-type="file" onclick="pickType(this,'file')">📄 DOCUMENT</button></div><input id="msgTitle" class="big-input" placeholder="Titre (facultatif)"><textarea id="msgBody" class="big-textarea" placeholder="Écris ta consigne, ton énigme, ton indice ou n'importe quelle transmission..."></textarea><input id="msgFile" type="file" class="file-input" accept="image/*,video/*,.pdf,.doc,.docx,.txt"><button class="send-main" onclick="sendMessage()">📩 ENVOYER MAINTENANT</button><div class="quick-row"><button onclick="sendPreset('💡 INDICE','Voici un indice pour vous aider.')">💡 INDICE</button><button onclick="sendPreset('⚠️ CONSIGNE','Nouvelle consigne du maître du jeu.')">⚠ CONSIGNE</button><button onclick="sendPreset('🔐 CONFIDENTIEL','Information confidentielle — à garder pour vous.')">🔐 SECRET</button></div></section>
