<section class="cockpit-card history-card"><div class="card-head"><div><span class="eyebrow">ACTIVITÉ</span><h2>Dernières transmissions</h2></div></div><div id="activity" class="activity-list"></div></section>
</div></main>
<script>
const gameId=<?=json_encode($id)?>,roles=<?=json_encode($roles,JSON_UNESCAPED_UNICODE)?>;let selectedType='text',source=null;
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function toast(t){const x=document.getElementById('toast');x.textContent=t;clearTimeout(window._tt);window._tt=setTimeout(()=>x.textContent='',2200)}
async function gm(action,extra={}){const fd=new URLSearchParams({id:gameId,action,...extra});const r=await fetch('/api/gm.php',{method:'POST',body:fd});const d=await r.json();if(!d.ok){toast(d.message||'Erreur');return;}toast(d.message||'OK');render(d.state||{});}
function pickType(btn,type){selectedType=type;document.querySelectorAll('.quick-types button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');}
async function sendMessage(){const fd=new FormData();fd.append('id',gameId);fd.append('action','send_message');fd.append('target_player_id',document.getElementById('target').value);fd.append('message_type',selectedType);fd.append('message_title',document.getElementById('msgTitle').value);fd.append('message_body',document.getElementById('msgBody').value);const f=document.getElementById('msgFile').files[0];if(f)fd.append('message_file',f);const r=await fetch('/api/gm.php',{method:'POST',body:fd});const d=await r.json();if(d.ok){toast('Transmission envoyée');document.getElementById('msgBody').value='';document.getElementById('msgTitle').value='';document.getElementById('msgFile').value='';render(d.state);}else toast(d.message||'Erreur');}
function sendPreset(title,body){document.getElementById('msgTitle').value=title;document.getElementById('msgBody').value=body;sendMessage();}
async function room(action,data){const fd=new FormData();fd.append('id',gameId);fd.append('action',action);Object.entries(data||{}).forEach(([k,v])=>fd.append(k,v));const r=await fetch('/api/gm.php',{method:'POST',body:fd});const d=await r.json();if(d.ok){toast(d.message||'Écran mis à jour');render(d.state);}else toast(d.message||'Erreur');}
function sendRoomText(){room('send_room',{room_type:'text',room_title:document.getElementById('roomTitle').value,room_body:document.getElementById('roomBody').value,room_url:document.getElementById('roomUrl').value});}
function roomPreset(type,title,body){document.getElementById('roomTitle').value=title;document.getElementById('roomBody').value=body;sendRoomText();}
function sendRoomFile(){const f=document.getElementById('roomFile').files[0];if(!f)return;const fd=new FormData();fd.append('id',gameId);fd.append('action','send_room');fd.append('room_type',f.type.startsWith('video')?'video':'image');fd.append('room_title',document.getElementById('roomTitle').value);fd.append('room_body',document.getElementById('roomBody').value);fd.append('room_file',f);fetch('/api/gm.php',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{toast(d.message||'Écran mis à jour');if(d.state)render(d.state);document.getElementById('roomFile').value='';});}
function clearRoom(){gm('clear_room')};function clearMailbox(){gm('clear_mailbox')};
async function assign(pid,rk){await gm('assign_role',{player_id:pid,role_key:rk});}
function render(st){const ps=st.players||[];document.getElementById('playerCount').textContent=ps.length;document.getElementById('players').innerHTML=ps.length?ps.map(p=>{const opts=Object.entries(roles).map(([k,v])=>`<option value="${esc(k)}" ${p.role_key===k?'selected':''}>${esc(v.label)}</option>`).join('');return `<div class="cockpit-player"><div class="cp-status ${p.online?'on':'off'}"></div><div class="cp-main"><strong>${esc(p.name)}</strong><small>${p.online?(p.ready?'🟢 EN PLACE':'🟢 CONNECTÉ'):'⚪ HORS LIGNE'}</small></div><select onchange="assign(${p.id},this.value)"><option value="">RÔLE...</option>${opts}</select><button class="cp-remove" onclick="gm('delete_player',{player_id:${p.id}})">×</button></div>`}).join(''):'<div class="empty">Aucun joueur connecté.</div>';document.getElementById('activity').innerHTML=(st.messages||[]).slice(0,10).map(m=>`<div class="activity-item"><b>${esc(m.title||'TRANSMISSION')}</b><span>${esc(m.body||m.type||'')}</span></div>`).join('')||'<div class="empty">Aucune transmission.</div>';}
async function refresh(){const r=await fetch('/api/gm.php?id='+gameId);const d=await r.json();if(d.ok)render(d.state)}
function connect(){try{source=new EventSource('/api/live.php?channel=admin&id='+gameId);source.addEventListener('refresh',refresh);source.onerror=()=>{source.close();setTimeout(connect,1200)}}catch(e){setTimeout(connect,1200)}}refresh();connect();
</script></body></html>
